@yjaaidi I would invert the types ([example](https://www.typescriptlang.org/play?#code/CYUwxgNghgTiAEAXAngBwQFQPYGsQDsAeDAPngF54BvfEAdwAoBKALngwF8BuAKB5AAeqLDETwAlvkQgYAMyhgEASXwArcIgDyqROKz4AztR7x4WHXvxQIAfjYAjLFgggo+XqYMgIsu-))

```typescript
declare type Token<T> = {new(): T};

export interface InjectOptions {
  optional?: boolean;
  self?: boolean;
  skipSelf?: boolean;
  host?: boolean;
}

class TestToken {}

declare function inject<T>(type: Token<T>, flags?: InjectOptions&{optional?: false}): T;
declare function inject<T>(type: Token<T>, flags: InjectOptions): T|null;

let value: TestToken;

value = inject(TestToken);
value = inject(TestToken, {self: true});
// Error: `null` is a potential return value:
value = inject(TestToken, {optional: true});

```
